 if(error)return `<section id="speech-usage-panel" class="panel" aria-labelledby="speech-usage-title">${heading}<p class="notice" role="alert">${esc(error)}</p></section>`;
 if(!t)return `<section id="speech-usage-panel" class="panel" aria-labelledby="speech-usage-title">${heading}<p role="status">正在读取语音用量…</p></section>`;
