 const card=(label,value,note)=>`<div class="speech-usage-metric"><dt>${label}</dt><dd>${esc(value)}</dd><p class="small muted">${esc(note)}</p></div>`;
 const metrics=`<dl class="speech-usage-metrics">${card('请求记录',t.attempts,`已发起 ${t.dispatched} · 未发出 ${t.released} · 处理中 ${t.inflight}`)}${card('成功合成',t.succeeded,'合成成功不代表已发送到 QQ')}${card('请求字符',characters(t),t.charactersUnknownAttempts?`${t.charactersUnknownAttempts} 条旧记录的字符数不可追溯`:'按请求报价记录，不等于腾讯已计费字符')}${card('成功合成估算',`¥${money(t.estimatedCny)}`,'标价估算，免费资源包抵扣未同步')}${card('待核对记录',t.unknown,'包括被拒绝或结果、费用尚未确认')}${card('尚未结算预留',`¥${money(t.reservedCny)}`,`其中待核对 ¥${money(t.unknownCny)}`)}</dl>`;
 const table=(rows,grouped=false)=>`<div class="table-wrap"><table class="speech-usage-table"><caption>${grouped?'按聊天汇总':'每日用量'}</caption><thead><tr><th scope="col">${grouped?'聊天':'日期'}</th><th scope="col">记录</th><th scope="col">成功</th><th scope="col">待核对</th><th scope="col">请求字符</th><th scope="col">成功估算</th><th scope="col">未结算预留</th></tr></thead><tbody>${rows.map(row=>`<tr><th scope="row">${esc(grouped?chatLabel(row.chatKey):row.date)}</th><td>${Number(row.attempts)}</td><td>${Number(row.succeeded)}</td><td>${Number(row.unknown)}</td><td>${esc(characters(row))}${row.charactersUnknownAttempts?`<span class="small muted"> · ${Number(row.charactersUnknownAttempts)} 条未知</span>`:''}</td><td>¥${money(row.estimatedCny)}</td><td>¥${money(row.reservedCny)}</td></tr>`).join('')}</tbody></table></div>`;
 const results=t.attempts?`${table(report.daily||[])}${range==='all'?`<details class="speech-usage-conversations"><summary>按群聊与私聊查看（${Number(report.conversationCount)||0} 个聊天）</summary>${table(report.conversations||[],true)}${report.conversationsTruncated?'<p class="small muted">仅展示记录最多的前200个聊天，合计包含全部有权查看的记录。</p>':''}</details>`:''}`:'<p class="muted">这个范围还没有语音合成记录。</p>';
