   if(drafts.has(chatKey)){state.editor={...drafts.get(chatKey)};state.dirty=true;}else if(!keepEditor){state.editor=state.personas.find(x=>x.id===scope()?.selected?.persona?.id)||state.personas[0]||null;state.dirty=false;}
