 function mode(register){registering=register;$('login-tab').setAttribute('aria-selected',!register);$('register-tab').setAttribute('aria-selected',register);$('auth-title').textContent=register?'创建你的账号':'欢迎回来';$('auth-note').textContent=register?'注册普通账号，开始管理自己的聊天。':'使用你的账号和密码登录。';$('auth-submit').textContent=register?'注册并登录':'登录';$('confirm-field').hidden=!register;$('confirm-password').required=register;$('password').minLength=register?10:0;let completion='current-password';if(register)completion='new-password';$('password').autocomplete=completion;status.textContent=register?'密码至少 10 个字符。':'';status.classList.remove('error');}
 try{const auth=await api('/api/auth/status');if(auth.authenticated){location.replace(safeReturnTo());return;}$('register-tab').disabled=!auth.registrationEnabled;$('auth-submit').disabled=!auth.configured;status.textContent=!auth.configured?'平台正在初始化，请联系管理员。':new URLSearchParams(location.search).has('changed')?'密码已修改，请重新登录。':'';}catch(error){status.textContent=error.message;status.classList.add('error');}
