 $('auth-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,data=Object.fromEntries(new FormData(form));if(registering&&data.password!==data.confirmPassword){status.textContent='两次输入的密码不一致。';return;}const button=$('auth-submit');button.disabled=true;try{await send('/api/auth/'+(registering?'register':'login'),{username:data.username,password:data.password});form.reset();location.replace(safeReturnTo());}catch(error){status.textContent=error.message;status.classList.add('error');}finally{button.disabled=false;}};
